using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns an animated emoji corresponding to a given emoji. Returns a 404 error if the emoji has no animated emoji
    /// </summary>
    public Task<TdLib.TdApi.Objects.AnimatedEmoji> GetAnimatedEmojiAsync(string emoji = default)
    {

           using var activity =  StartCallActivity("GetAnimatedEmojiAsync", typeof(GetAnimatedEmoji).FullName ?? "GetAnimatedEmojiAsync");

           try
           {
             return client.GetAnimatedEmojiAsync(emoji);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
